package com.bank.uc;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.logging.Logger;

// Account-level metastore: three-level namespace + group membership + grants.
class Metastore {
    private static final Logger log = Logger.getLogger(Metastore.class.getName());

    // group -> set of "catalog.schema.table:PRIVILEGE"
    private final Map<String, Set<String>> grants = new HashMap<>();
    // user -> groups (synced from identity provider)
    private final Map<String, Set<String>> userGroups = new HashMap<>();

    void addUserToGroup(String user, String group) {
        userGroups.computeIfAbsent(user, u -> new HashSet<>()).add(group);
        log.info(() -> "Identity sync: " + user + " added to group " + group);
    }

    // Removing a user from the IdP revokes access EVERYWHERE at once.
    void removeUser(String user) {
        userGroups.remove(user);
        log.warning(() -> "Identity sync: " + user + " removed from IdP → access revoked across ALL workspaces");
    }

    void grant(String privilege, String fqTable, String group) {
        grants.computeIfAbsent(group, g -> new HashSet<>()).add(fqTable + ":" + privilege);
        log.info(() -> "GRANT " + privilege + " ON " + fqTable + " TO " + group);
    }

    boolean userHas(String user, String privilege, String fqTable) {
        Set<String> groups = userGroups.getOrDefault(user, Set.of());
        for (String g : groups) {
            if (grants.getOrDefault(g, Set.of()).contains(fqTable + ":" + privilege)) return true;
        }
        return false;
    }
}
