package com.bank.uc;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Central, queryable audit log of every access across all workspaces.
class AuditLog {
    private static final Logger log = Logger.getLogger(AuditLog.class.getName());

    private final List<String> entries = new ArrayList<>();

    void record(String user, String action, String fqTable, boolean allowed) {
        String entry = user + " " + action + " " + fqTable + " → " + (allowed ? "ALLOWED" : "DENIED");
        entries.add(entry);
        log.fine(() -> "AUDIT: " + entry);
    }

    List<String> query(String fqTable) {
        return entries.stream().filter(e -> e.contains(fqTable)).toList();
    }
}
