package com.bank.uc;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Records table lineage: which tables a table was derived FROM.
class LineageGraph {
    private static final Logger log = Logger.getLogger(LineageGraph.class.getName());

    private final Map<String, List<String>> derivedFrom = new HashMap<>();

    void recordDerivation(String target, List<String> sources) {
        derivedFrom.put(target, sources);
        log.info(() -> "Lineage: " + target + " derived from " + sources);
    }

    // Trace all upstream ancestors (how was this table built?).
    List<String> traceUpstream(String table) {
        List<String> all = new ArrayList<>();
        List<String> sources = derivedFrom.getOrDefault(table, List.of());
        for (String s : sources) {
            all.add(s);
            all.addAll(traceUpstream(s));
        }
        return all;
    }
}
