package com.bank.uc;

import java.util.logging.Logger;

// Enforces grants, applies column masks and row filters, records audit entries.
class AccessController {
    private static final Logger log = Logger.getLogger(AccessController.class.getName());

    private final Metastore metastore;
    private final AuditLog audit;
    private final boolean maskAccountNumber;

    AccessController(Metastore metastore, AuditLog audit, boolean maskAccountNumber) {
        this.metastore = metastore;
        this.audit = audit;
        this.maskAccountNumber = maskAccountNumber;
    }

    // Reads a row for a user, enforcing SELECT grant and masking the account number.
    String readRow(String user, String fqTable, String accountNumber, long amount) {
        boolean allowed = metastore.userHas(user, "SELECT", fqTable);
        audit.record(user, "SELECT", fqTable, allowed);
        if (!allowed) {
            log.warning(() -> "ACCESS DENIED: " + user + " cannot SELECT " + fqTable);
            return null;
        }
        String shown = maskAccountNumber ? mask(accountNumber) : accountNumber;
        log.info(() -> user + " read " + fqTable + ": account=" + shown + " amount=" + amount);
        return shown;
    }

    private String mask(String account) {
        if (account.length() <= 4) return "****";
        return "****" + account.substring(account.length() - 4); // show last 4 only
    }
}
