package com.bank.uc;

import java.util.List;
import java.util.logging.Logger;

public class UnityCatalogDemo {
    private static final Logger log = Logger.getLogger(UnityCatalogDemo.class.getName());

    public static void main(String[] args) {
        Metastore metastore = new Metastore();
        AuditLog audit = new AuditLog();
        AccessController controller = new AccessController(metastore, audit, true);

        String tradesTable = "banking_prod.trades.settlements";

        // Identity sync + central grant to a group.
        metastore.addUserToGroup("priya_analyst", "risk_analysts");
        metastore.addUserToGroup("contractor_bob", "risk_analysts");
        metastore.grant("SELECT", tradesTable, "risk_analysts");

        // Authorized read — account number is masked.
        controller.readRow("priya_analyst", tradesTable, "SAV2001789", 50000);

        // Contractor leaves: removed from IdP → access revoked everywhere.
        metastore.removeUser("contractor_bob");
        controller.readRow("contractor_bob", tradesTable, "CUR3001456", 80000);

        // Central audit query for the table.
        log.info(() -> "AUDIT for " + tradesTable + ": " + audit.query(tradesTable));

        // Column-level lineage: gold report ← silver ← bronze.
        LineageGraph lineage = new LineageGraph();
        lineage.recordDerivation("banking_prod.trades.bronze_raw", List.of("kafka.trade_events"));
        lineage.recordDerivation("banking_prod.trades.silver_clean", List.of("banking_prod.trades.bronze_raw"));
        lineage.recordDerivation("banking_prod.reports.fraud_gold",
                List.of("banking_prod.trades.silver_clean"));
        log.info(() -> "Upstream of fraud_gold: " + lineage.traceUpstream("banking_prod.reports.fraud_gold"));
    }
}
